#!/bin/bash

umask 077

echo "This software is governed by the terms and conditions of a licence agreement with Sophos Limited: https://www.sophos.com/en-us/legal/sophos-end-user-terms-of-use"

export VERSION=1.3.7.71
PRODUCT_NAME="Sophos Protection for Linux"
INSTALL_FILE=$0


EXITCODE_SUCCESS=0
EXITCODE_NOT_LINUX=1
EXITCODE_NOT_ROOT=2
EXITCODE_NO_CENTRAL=3
EXITCODE_NOT_ENOUGH_MEM=4
EXITCODE_NOT_ENOUGH_SPACE=5
EXITCODE_FAILED_REGISTER=6
EXITCODE_ALREADY_INSTALLED=7
EXITCODE_SAV_INSTALLED=8
EXITCODE_NOT_64_BIT=9
EXITCODE_DOWNLOAD_FAILED=10
EXITCODE_FAILED_TO_UNPACK=11
EXITCODE_CANNOT_MAKE_TEMP=12
EXITCODE_VERIFY_INSTALLER_FAILED=13
EXITCODE_SYMLINKS_FAILED=14
EXITCODE_CHMOD_FAILED=15
EXITCODE_NOEXEC_TMP=16
EXITCODE_DELETE_INSTALLER_ARCHIVE_FAILED=17
EXITCODE_BASE_INSTALL_FAILED=18
EXITCODE_BAD_INSTALL_PATH=19
EXITCODE_INSTALLED_BUT_NO_PATH=20
EXIT_FAIL_WRONG_LIBC_VERSION=21
EXIT_FAIL_COULD_NOT_FIND_LIBC_VERSION=22
EXITCODE_UNEXPECTED_ARGUMENT=23
EXITCODE_BAD_GROUP_NAME=24
EXITCODE_GROUP_NAME_EXCEEDS_MAX_SIZE=25
EXITCODE_DUPLICATE_ARGUMENTS_GIVEN=26
EXITCODE_BAD_PRODUCT_SELECTED=27
EXITCODE_INVALID_CUSTOM_ID_GIVEN=28
EXITCODE_NO_SYSTEMD=29
EXITCODE_MISSING_PACKAGE=30
EXITCODE_INVALID_CA_PATHS=31
EXITCODE_INVALID_MR_UC_GIVEN=32
EXITCODE_COMPATIBILITY_CHECKS_FAILED=33
EXITCODE_MALFORMED_THININSTALLER=34
EXITCODE_WRONG_PERMISSION_PASSWD=35
EXITCODE_WRONG_PERMISSION_RESOLV_CONF=36
EXITCODE_REGISTRATION_FAILED=51
EXITCODE_AUTHENTICATION_FAILED=52
EXITCODE_ALC_POLICY_TRANSLATION_FAILED=53
EXITCODE_ABSENT_MEMORY_PERCENTAGE=54
EXITCODE_ABSENT_CPU_PERCENTAGE=55
EXITCODE_BAD_CGROUP_LIMIT_PERCENTAGE=56
EXITCODE_INSUFFICENT_MEMORY_PERCENTAGE_LIMIT=57
EXIT_CODE_TAEGIS_TENANT_ID_MISTMATCH=58

PROXY_CREDENTIALS=

MAX_GROUP_NAME_SIZE=1024
VALID_PRODUCTS=("antivirus" "mdr" "xdr" "all")
REQUEST_NO_PRODUCTS="none"
SUMMARY="success"
FINISHED_DATE=""

BUILD_LIBC_VERSION=2.17

DAT_FILES=("supplement/sdds3.ScheduledQueryPack.dat"
    "supplement/sdds3.ML_MODEL4_LINUX_X86_64.dat"
    "supplement/sdds3.DataSetA.dat"
    "supplement/sdds3.LocalRepData.dat"
    "supplement/sdds3.RuntimeDetectionRules.dat"
    "supplement/sdds3.SSPLFLAGS.dat")

VALID_CENTRAL_CONNECTION=0
VALID_SUS_CONNECTION=0
VALID_CDN_CONNECTION=0

# If TMPDIR has not been set then default it to /tmp
if [[ -z "${TMPDIR}" ]]; then
    TMPDIR=/tmp
    export TMPDIR
fi

# Ensure PATH contains /usr/sbin and /sbin
export PATH=$PATH:/usr/sbin:/sbin

function log_info() {
    echo "INFO: ${1}"
}

function log_debug() {
    [[ -n "${DEBUG_THIN_INSTALLER}" ]] && echo "DEBUG: ${1}"
}

function log_warn() {
    COMPATIBILITY_WARNING_FOUND=1
    echo "WARN: ${1}"
}

function curl_debug() {
    local curl_output
    curl_output="$1"
    log_debug "See curl output for more detail:"
    log_debug "$curl_output"
}

function check_install_path_has_correct_permissions()
{
    local sophos_install=${SOPHOS_INSTALL:-/opt/sophos-spl}
    [[ "${sophos_install}" = /* ]] || return

    # loop through given install path from right to left to find the first directory that exists.
    local install_path="${sophos_install%/*}"

    # Make sure that the install_path string is not empty, in the case of "/foo"
    if [[ -z "$install_path" ]]; then
        install_path="/"
    fi

    while [[ ! -d "${install_path}" ]]; do
        install_path="${install_path%/*}"

        # Make sure that the install_path string is not empty.
        if [[ -z "$install_path" ]]; then
            install_path="/"
        fi
    done

    # continue looping through all the existing directories ensuring that the current permissions will allow sophos-spl to execute

    while [[ "${install_path}" != "/" ]]; do
        permissions=$(stat -c '%A' "${install_path}")
        if [[ ${permissions: -1} != "x" ]]; then
            failure ${EXITCODE_BAD_INSTALL_PATH} "ERROR: SPL installation will fail, can not install to ${sophos_install} because ${install_path} does not have correct execute permissions. Requires execute rights for all users"
        fi

        install_path="${install_path%/*}"

        if [[ -z "$install_path" ]]; then
            install_path="/"
        fi
    done
    success
}

function is_sspl_installed() {
    systemctl list-unit-files | grep -q sophos-spl
}

function verify_install_directory() {
    # No custom install location so use default or special case if SOPHOS_INSTALL is set to the default, then we just use it and don't append
    if [[ (-z "${SOPHOS_INSTALL}") || ("${SOPHOS_INSTALL}" == "/opt/sophos-spl") ]]; then
        export SOPHOS_INSTALL=/opt/sophos-spl
        [ ${FORCE_INSTALL} -eq 0 ] && ! is_sspl_installed && [ -d "${SOPHOS_INSTALL}" ] && failure ${EXITCODE_BAD_INSTALL_PATH} "The intended destination for ${PRODUCT_NAME}: ${SOPHOS_INSTALL} already exists. Please either move or delete this directory."
        check_install_path_has_correct_permissions
        success
        return
    fi

    # Remove trailing /
    SOPHOS_INSTALL="${SOPHOS_INSTALL%/}"

    # Sophos install must be in an ASCII path - no spaces
    local LEFT_OVER=$(echo ${SOPHOS_INSTALL} | tr -d '[:alnum:]_/.-')

    if [[ -n "${LEFT_OVER}" ]]; then
        local SPACES=$(echo ${SOPHOS_INSTALL} | sed -e's/[^ ]//g')
        if [[ -n "${SPACES}" ]]; then
            failure ${EXITCODE_BAD_INSTALL_PATH} "ERROR: SPL installation will fail, can not install to '${SOPHOS_INSTALL}' because it contains spaces."
        else
            failure ${EXITCODE_BAD_INSTALL_PATH} "ERROR: SPL installation will fail, can not install to '${SOPHOS_INSTALL}' because it contains non-alphanumeric characters: ${LEFT_OVER}"
        fi
    fi

    realPath=$(realpath -m "${SOPHOS_INSTALL}")
    [[ "${SOPHOS_INSTALL}" = /* ]] || failure ${EXITCODE_BAD_INSTALL_PATH} "ERROR: SPL installation will fail, can not install to '${SOPHOS_INSTALL}' because it is a relative path. To install under this directory, please re-run with --install-dir=${realPath}"
    [[ "${realPath}" != "${SOPHOS_INSTALL}" ]] && failure ${EXITCODE_BAD_INSTALL_PATH} "ERROR: SPL installation will fail, can not install to '${SOPHOS_INSTALL}'. To install under this directory, please re-run with --install-dir=${realPath}"
    [[ -f "${SOPHOS_INSTALL}" ]] && failure ${EXITCODE_BAD_INSTALL_PATH} "ERROR: SPL installation will fail, can not install to '${SOPHOS_INSTALL}' as it is a file"

    # SOPHOS_INSTALL is custom dirname to contain sophos-spl
    export SOPHOS_INSTALL="$SOPHOS_INSTALL/sophos-spl"

    # Check that the install path has valid permission on the existing directories
    check_install_path_has_correct_permissions
    success
}

function verify_compatible_glibc_version() {
    system_libc_version=$(ldd --version | grep 'ldd (.*)' | rev | cut -d ' ' -f 1 | rev)
    lowest_version=$(printf '%s\n' ${BUILD_LIBC_VERSION} "${system_libc_version}" | sort -V | head -n 1) || failure ${EXIT_FAIL_COULD_NOT_FIND_LIBC_VERSION} "ERROR: SPL installation will fail, could not determine libc version"
    if [[ "${lowest_version}" != "${BUILD_LIBC_VERSION}" ]]; then
        failure ${EXIT_FAIL_WRONG_LIBC_VERSION} "ERROR: SPL installation will fail, can not install on unsupported system. Detected GLIBC version ${system_libc_version} < required ${BUILD_LIBC_VERSION}"
    fi
    success
}

function verify_installed_packages() {

    av_packages=("setcap")
    for package in "${av_packages[@]}"; do
        [[ -z $(which "${package}") ]] && log_warn "AV Plugin requires ${package} to be installed on this server. SPL can be installed but AV will not work"
    done
    compatibility_packages=("curl")
    for package in "${compatibility_packages[@]}"; do
        [[ -z $(which "${package}") ]] && log_warn "Cannot continue pre-install checks that require ${package} to be installed on this server. Please run installer with --notest to run installer without pre-install checks"
    done
    success
}

function check_free_storage()
{
    local space="$1"
    local sophos_install=${SOPHOS_INSTALL:-/opt/sophos-spl}
    [[ "${sophos_install}" = /* ]] || return
    local install_path="${sophos_install%/*}"

    # Loop through directory path from right to left, finding the first part of the path that exists.
    # Then we will use the df command on that path.  df command will fail if used on a path that does not exist.
    while [[ ! -d "${install_path}" ]]; do
        install_path="${install_path%/*}"

        # Make sure that the install_path string is not empty.
        if [[ -z "$install_path" ]]; then
            install_path="/"
        fi
    done

    local free=$(df -kP "${install_path}" | sed -e "1d" | awk '{print $4}')
    local mountpoint=$(df -kP "${install_path}" | sed -e "1d" | awk '{print $6}')

    local free_mb
    free_mb=$((free / 1024))

    if [[ ${free_mb} -gt ${space} ]]; then
        success
        return 0
    fi
    failure ${EXITCODE_NOT_ENOUGH_SPACE} "ERROR: SPL installation will fail as there is not enough space in ${mountpoint} to install SPL. You need at least ${space}MiB to install SPL"
}

function check_total_mem() {
    local neededMemKiloBytes=$1
    local totalMemKiloBytes=$(grep MemTotal /proc/meminfo | awk '{print $2}')

    if [ "${totalMemKiloBytes}" -gt "${neededMemKiloBytes}" ]; then
        success
        return 0
    fi
    failure ${EXITCODE_NOT_ENOUGH_MEM} "ERROR: SPL installation will fail as this machine does not meet product requirements (total RAM: ${totalMemKiloBytes}kB). The product requires at least ${neededMemKiloBytes}kB of RAM"
}

function check_ca_certs() {
    if [[ -f "/etc/ssl/certs/ca-certificates.crt" ]]; then
        log_debug "Installation will use system CA path '/etc/ssl/certs/ca-certificates.crt'"
    elif [[ -f "/etc/pki/tls/certs/ca-bundle.crt" ]]; then
        log_debug "Installation will use system CA path '/etc/pki/tls/certs/ca-bundle.crt'"
    elif [[ -f "/etc/ssl/ca-bundle.pem" ]]; then
        log_debug "Installation will use system CA path '/etc/ssl/ca-bundle.pem'"
    else
        failure ${EXITCODE_INVALID_CA_PATHS} "ERROR: SPL installation will fail as the system CA path could not be found. SPL uses either '/etc/ssl/certs/ca-certificates.crt', '/etc/pki/tls/certs/ca-bundle.crt' or '/etc/ssl/ca-bundle.pem'"
    fi
    success
}

function check_etc_passwd_permission() {
    permissions=$(stat -c '%A' "/etc/passwd")
    if [[ ${permissions:7:1} != "r" ]]
    then
        failure ${EXITCODE_WRONG_PERMISSION_PASSWD} "ERROR: SPL installation will fail as /etc/passwd is not world-readable"
    fi
}

function verify_system_requirements() {
    # Check that the OS is Linux
    [[ $(uname -a) =~ "Linux" ]] || failure ${EXITCODE_NOT_LINUX} "ERROR: SPL installation will fail as it can only be installed on Linux"

    # Check machine architecture
    if [[ $(uname -m) = "x86_64" || $(uname -m) = "aarch64" ]]; then
        BIN="bin"
    else
        failure ${EXITCODE_NOT_64_BIT} "ERROR: SPL installation will fail as it can only be installed on a x86_64 or aarch64 system"
    fi

    # Check for systemd
    [[ $(ps -p 1 -o comm=) == "systemd" ]] || failure ${EXITCODE_NO_SYSTEMD} "ERROR: SPL installation will fail as it requires systemd to run"

    # Check  /etc/resolv.conf
    permissions=$(stat -L -c "%a" /etc/resolv.conf)
    [[ ${permissions: -1} < 4 ]] && failure ${EXITCODE_WRONG_PERMISSION_RESOLV_CONF} "ERROR: SPL installation will fail as Sophos cannot read /etc/resolv.conf (Permission denied). Update the permissions for this file before reattempting installation"

    # Check required packages are installed
    verify_installed_packages

    # Check kernel supports GLIBC version 2.17 or later
    verify_compatible_glibc_version

    # Check server has capabilities
    [[ (-z $(which getcap)) || (-z $(which setcap)) ]] && log_warn "SPL requires capabilities for the AV plugin to be installed. The base installation will succeed but this plugin will not be operational"

    # Check Fanotify is enabled in kernel
    fanotify_config=$(cat /boot/config-"$(uname -r)" 2>/dev/null | grep FANOTIFY 2>/dev/null)
    [[ ("${fanotify_config}" =~ "CONFIG_FANOTIFY=y") && ("${fanotify_config}" =~ "CONFIG_FANOTIFY_ACCESS_PERMISSIONS=y") ]] || log_warn "Fanotify is not enabled by this kernel so the AV plugin will not be able to scan files on access and, if necessary, block access to threats. SPL can be installed but OnAccess scanning will not be operational, see https://support.sophos.com/support/s/article/KB-000034610 for more details"

    # Check there is enough disk space
    check_free_storage 2048

    # Check there is enough RAM (930000kB)
    check_total_mem 930000

    # Check System CA certificate locations
    check_ca_certs

    # Check /etc/passwd can be accessed by non-root processes
    check_etc_passwd_permission

    success
}

function verify_connection_to_central() {
    local proxy=$1
    local curl_output
    if [[ -z ${proxy} ]]; then
        curl_output=$(OPENSSL_CONF=/dev/null curl --tlsv1.2 --noproxy '*' -k -is "${CENTRAL_URL}" -m 60 -v 2>&1)
        curl_exitcode=$?
        if [[ $curl_exitcode == 0 ]]; then
            VALID_CENTRAL_CONNECTION=1
            log_info "Server can connect to Sophos Central directly"
        else
            log_warn "Server cannot connect to Sophos Central directly"
            curl_debug "$curl_output"
        fi
    else
        curl_output=$(OPENSSL_CONF=/dev/null curl --tlsv1.2 --proxy "${proxy}" -k -is "${CENTRAL_URL}" -m 60 -v 2>&1)
        curl_exitcode=$?
        if [[ $curl_exitcode == 0 ]]; then
            VALID_CENTRAL_CONNECTION=1
            log_info "Server can connect to Sophos Central via ${proxy}"
        else
            log_warn "SPL installation will not be performed via ${proxy}. Server cannot connect to Sophos Central via ${proxy}"
            curl_debug "$curl_output"
        fi
    fi
}

function verify_all_possible_connections_to_central()
{
    # Check connection to Central
    log_info "Verifying connections to Sophos Central"
    verify_connection_to_central
    [[ -n "${PROXY}" ]] && verify_connection_to_central "${PROXY}"
    for message_relay in "${MESSAGE_RELAYS[@]}"; do
        verify_connection_to_central "${message_relay}"
    done
    if [[ "${VALID_CENTRAL_CONNECTION}" == 0 ]]
    then
        log_error "SPL installation will fail as a connection to Sophos Central could not be established"
    else
        success
    fi
}

function verify_connection_to_sus() {
    local proxy=$1
    local curl_output
    if [[ -z ${proxy} ]]; then
        curl_output=$(OPENSSL_CONF=/dev/null curl --tlsv1.2 --noproxy '*' -is "${SUS_URL}" -m 60 -v 2>&1)
        curl_exitcode=$?
        if [[ $curl_exitcode == 0 ]]; then
            VALID_SUS_CONNECTION=1
            log_info "Server can connect to the SUS server (${SUS_URL}) directly"
        else
            log_warn "Server cannot connect to the SUS server (${SUS_URL}) directly"
            curl_debug "$curl_output"
        fi
    else
        curl_output=$(OPENSSL_CONF=/dev/null curl --tlsv1.2 --proxy "${proxy}" -is "${SUS_URL}" -m 60 -v 2>&1)
        curl_exitcode=$?
        if [[ $curl_exitcode == 0 ]]; then
            VALID_SUS_CONNECTION=1
            log_info "Server can connect to the SUS server (${SUS_URL}) via ${proxy}"
        else
            log_warn "SPL installation will not be performed via ${proxy}. Server cannot connect to the SUS server (${SUS_URL}) via ${proxy}"
            curl_debug "$curl_output"
        fi
    fi
}

function verify_all_possible_connections_to_sus()
{
      # Check connection to SUS
      log_info "Verifying connections to Sophos Update Service (SUS) server"
      if [[ -n $OVERRIDE_SUS_LOCATION ]]; then
          SUS_URL="$OVERRIDE_SUS_LOCATION"
          echo "Using SUS URL override: $OVERRIDE_SUS_LOCATION"
      elif [[ -n $sus_url_arg ]]; then
          SUS_URL="$sus_url_arg"
          log_debug "Using SUS URL from Central"
      else
          SUS_URL="https://sus.sophosupd.com"
          log_debug "Using default SUS URL"
      fi
      verify_connection_to_sus
      [[ -n "${PROXY}" ]] && verify_connection_to_sus "${PROXY}"
      for message_relay in "${MESSAGE_RELAYS[@]}"; do
          verify_connection_to_sus "${message_relay}"
      done

      if [[ "${VALID_SUS_CONNECTION}" == 0 ]]
      then
          log_error "SPL installation will fail as a connection to the SUS server could not be established"
      else
          success
      fi
}

function verify_connection_to_cdn() {
    local cdn_url=$1
    local proxy=$2

    if [[ -z ${proxy} ]]; then
        successful_downloads=0
        for supplement in "${DAT_FILES[@]}"; do
            if OPENSSL_CONF=/dev/null curl --tlsv1.2 --noproxy '*' -is "${cdn_url}/${supplement}" -m 60 >/dev/null 2>&1; then
                successful_downloads=$((successful_downloads + 1))
                log_debug "Connection verified to CDN server, server is able to download ${supplement#*/} supplement from ${cdn_url} directly"
            else
                log_warn "Failed to get supplement from CDN server (${cdn_url}) directly"
            fi
        done

        if [[ "${successful_downloads}" -eq "${#DAT_FILES[@]}" ]]; then
            VALID_CDN_CONNECTION=1
            log_info "Connection verified to CDN server, server was able to download all SPL packages directly"
        fi
    else
        successful_downloads=0
        for supplement in "${DAT_FILES[@]}"; do
            if OPENSSL_CONF=/dev/null curl --tlsv1.2 --proxy "${PROXY}" -is "${cdn_url}/${supplement}" -m 60 >/dev/null 2>&1; then
                successful_downloads=$((successful_downloads + 1))
                log_debug "Connection verified to CDN server via proxy (${proxy}). Server is able to download ${supplement#*/} supplement from ${cdn_url} via ${proxy}"
            else
                log_warn "SPL installation will not be performed via proxy (${proxy}). Failed to download ${supplement#*/} supplement from CDN server (${cdn_url}) via ${proxy}"
            fi
        done
        if [[ "${successful_downloads}" -eq "${#DAT_FILES[@]}" ]]; then
            VALID_CDN_CONNECTION=1
            log_info "Connection verified to CDN server, server was able to download all SPL packages via ${proxy}"
        fi
    fi
}

function verify_all_possible_connections_to_cdn()
{
    # Check connection to CDN
    log_info "Verifying connections to the CDN server"
    if [[ -n $OVERRIDE_CDN_LOCATION ]]; then
        CDN_URLS=("$OVERRIDE_CDN_LOCATION")
        echo "Using CDN URL override: $OVERRIDE_CDN_LOCATION"
    elif [[ ${#cdn_urls_arg[@]} != 0 ]]
    then
        CDN_URLS=("${cdn_urls_arg[@]}")
        log_debug "Using CDN URLs from Central"
    else
        CDN_URLS=("https://sdds3.sophosupd.com:443" "https://sdds3.sophosupd.net:443")
        log_debug "Using default CDN URLs"
    fi
    CDN_URL=""
    for url in "${CDN_URLS[@]}"; do
        if OPENSSL_CONF=/dev/null curl --tlsv1.2 --noproxy '*' -is ${url} -m 60 >/dev/null 2>&1; then
            CDN_URL="${url}"
            log_info "Server can connect to CDN address (${CDN_URL}) directly"
            break
        else
            log_debug "Server cannot connect to CDN address (${url}) directly"
        fi
    done
    if [[ -z "$CDN_URL" ]]
    then
        if [[ -z "${PROXY}" ]]; then
            if [[ "${VALID_UPDATE_CACHE_CONNECTION}" == 1 ]]; then
                log_warn "A direct connection to a CDN server could not be established"
            else
                log_error "SPL installation will fail as a connection to a CDN server could not be established" "verify_connection_to_cdn"
            fi
        else
            for url in "${CDN_URLS[@]}"; do
               if OPENSSL_CONF=/dev/null curl --tlsv1.2 --proxy "${PROXY}" -is ${url} -m 60 >/dev/null 2>&1; then
                   log_debug "Server can connect to CDN address (${url}) via ${PROXY}"
                   CDN_URL="${url}"
                   break
               else
                   log_warn "Server cannot connect to any CDN address via ${PROXY}"
               fi
            done
            [[ -z "${CDN_URL}" ]] && log_error "SPL installation will fail as the server cannot connect to any CDN server directly or via a proxy" "verify_connection_to_cdn"
        fi
    fi

    if [[ -n "${CDN_URL}" ]]; then
        verify_connection_to_cdn "${CDN_URL}"
        [[ -n "${PROXY}" ]] && verify_connection_to_cdn "${CDN_URL}" "${PROXY}"
    fi

    if [[ "${VALID_CDN_CONNECTION}" == 0 && "${VALID_UPDATE_CACHE_CONNECTION}" == 0 ]]
    then
        log_error "SPL installation will fail as the server is not able to download packages from the CDN server"
    else
        success
    fi
}

function verify_network_connections() {
    if [[ -z $(which "curl") ]]; then
        log_warn "Unable to run network connectivity checks as curl is not installed on this server"
        return
    fi

    IFS=' ' read -ra MESSAGE_RELAYS <<<"${1}"
    IFS=' ' read -ra UPDATE_CACHES <<<"${2}"
    IFS=' ' read -ra cdn_urls_arg <<<"${3}"
    sus_url_arg="${4}"

    [[ ${#UPDATE_CACHES[@]} != 0 ]] && log_info "Verifying connections to configured Update Caches"
    local curl_output
    for update_cache in "${UPDATE_CACHES[@]}"; do
        curl_output=$(OPENSSL_CONF=/dev/null curl --tlsv1.2 -k -is "https://${update_cache}/v3" -m 60 -v 2>&1)
        curl_exitcode=$?
        if [[ $curl_exitcode == 0 ]]; then
            VALID_UPDATE_CACHE_CONNECTION=1
            log_info "Server can connect to configured Update Cache (${update_cache})"
        else
            log_warn "Server cannot connect to configured Update Cache (${update_cache})"
            curl_debug "$curl_output"
        fi
    done

    if [[ -n "${https_proxy}" ]]; then
        log_debug "Network connections will be tested with the configured https_proxy: ${https_proxy}"
        PROXY="${https_proxy}"
    elif [[ -n "${HTTPS_PROXY}" ]]; then
        log_debug "Network connections will be tested with the configured HTTPS_PROXY: ${HTTPS_PROXY}"
        PROXY="${HTTPS_PROXY}"
    elif [[ -n ${http_proxy} ]]; then
        log_debug "Network connections will be tested with the configured http_proxy: ${http_proxy}"
        PROXY="${http_proxy}"
    fi

    verify_all_possible_connections_to_central
    verify_all_possible_connections_to_sus
    verify_all_possible_connections_to_cdn
}

function verify_necessary_binaries() {

    binaries_missing=""
    binaries_required=("awk" "basename" "bash" "cat" "chmod" "chown" "cmp" "cp" "cut" "date" "df" "dirname" "expr"
    "find" "flock" "getent" "grep" "groupadd" "gzip" "head" "hostname" "id" "ldd" "ln" "ls" "mkdir" "mktemp" "mv" "od" "pgrep"
    "pkill" "pwd" "rev" "rm" "sed" "sleep" "sort" "stat" "systemctl" "tail" "tar" "test" "timeout" "touch" "truncate" "umount"
    "uname" "useradd" "usermod" "xargs")

    PATH="$PATH:/usr/sbin"

    if [[ (-z $(which "which")) ]]; then
        failure ${EXITCODE_MISSING_PACKAGE} "ERROR: SPL installation will fail as it requires the 'which' package to do pre-install checks. Please either install which before attempting SPL installation again, or run installer with --notest to run installation without pre-install checks"
        return
    fi

    for binary in "${binaries_required[@]}"; do
        if [[ (-z $(which "${binary}")) ]]; then
            fail_binary_check=true
            if [[ -z "$binaries_missing" ]]; then
                binaries_missing+=$binary
            else
                binaries_missing+=", $binary"
            fi
        fi
    done
    [[ $fail_binary_check == true ]] && failure ${EXITCODE_MISSING_PACKAGE} "ERROR: SPL installation will fail as it requires the following package(s) to be installed on this server: ${binaries_missing}. Please install before attempting SPL installation again"
}


# Ensure override is unset so that it can only be set when explicitly passed in by the user with --allow-override-mcs-ca
unset ALLOW_OVERRIDE_MCS_CA

CREATED_INSTALL_DIRECTORY=0

function get_help_text() {
  echo "${PRODUCT_NAME} Installer, help:"
  echo "Note: Please refer to https://docs.sophos.com/central/customer/help/en-us/index.html?contextId=protect-devices-server-CLI-Linux for advanced options"
  echo "Usage: [options]"
  echo "Valid options are:"
  echo -e "--help [-h]\t\t\tDisplay this summary"
  echo -e "--version [-v]\t\t\tDisplay version of installer"
  echo -e "--force\t\t\t\tForce re-install"
  echo -e "--group=<group>\t\t\tAdd this endpoint into the Sophos Central group specified"
  echo -e "--group=<path to sub group>\tAdd this endpoint into the Sophos Central nested\n\t\t\t\tgroup specified where path to the nested group\n\t\t\t\tis each group separated by a backslash\n\t\t\t\ti.e. --group=<top-level group>\\\\\<sub-group>\\\\\<bottom-level-group>\n\t\t\t\tor --group='<top-level group>\\\<sub-group>\\\<bottom-level-group>'"
  echo -e "--products='<products>'\t\tComma separated list of products to install\n\t\t\t\ti.e. --products=antivirus,mdr,xdr"
  echo -e "--message-relays=<host1>:<port1>,<host2>:<port2>\n\t\t\t\tSpecify message relays used for registration.\n\t\t\t\t To specify no message relays use --message-relays=none"
  echo -e "--update-caches=<hostname1>:<port1>,<hostname2>:<port2>\n\t\t\t\tSpecify update caches used for install.\n\n\t\t\t\tThe host part of the update cache must be its hostname as defined in Central,\n\t\t\t\tusing the ip address of the update cache is not supported\n\t\t\t\t\tTo specify no update caches use --update-caches=none"
  echo -e "--test\t\t\t\tOnly run pre-installation checks and do not install SPL"
  echo -e "--notest\t\t\tDon't run any pre-installation checks and proceed with installing SPL"
  echo -e "--override-hostname=<hostname>\t\t\tOverride the default system hostname used throughout SPL and Sophos Central"
  echo -e "--skip-taegis-tenant-id-check\t\t\tSkip check that local Taegis Tenant ID matches one from Sophos Central account"
  echo -e "--skip-taegis-uninstall\t\t\tSkip uninstall of Taegis Agent following successfully installation of SPL"
  echo -e "--skip-redcloak-uninstall\t\t\tSkip uninstall of Redcloak following successfully installation of SPL"
}


function cleanup_and_exit() {
    code=$1

    if [[ -n "$BIN" && -x "${BIN}/telemetry" ]]
    then
        RESULT_CODE="$code" \
          "${BIN}/telemetry" "$CREDENTIALS_FILE_PATH" \
          "${SOPHOS_TEMP_DIRECTORY}"/*.ini \
          "${SOPHOS_TEMP_DIRECTORY}/mcsPolicy.config"
    fi

    if [[ "${code}" -eq "${EXITCODE_SUCCESS}" ]]; then
        [[ -z "${OVERRIDE_INSTALLER_CLEANUP}" ]] && rm -rf "${SOPHOS_TEMP_DIRECTORY}"

        # Start product if it is not running
        [[ $(systemctl is-active --quiet sophos-spl) ]] || systemctl start sophos-spl 2>/dev/null
    fi

    exit "${code}"
}

function write_check_result()
{
    if [[ -z ${PRE_INSTALL_TEST_ONLY} ]]
    then
        key=${1}
        shift
        value="$@"
        ini_file="${SOPHOS_TEMP_DIRECTORY}/thininstaller_report.ini"
        if ! grep -q "${key}" "${ini_file}" 2>/dev/null
        then
          (umask 0177 && echo "${key} = ${value}" >> "${ini_file}")
        fi
    fi
}

function write_args_to_file()
{
    if [[ -z ${PRE_INSTALL_TEST_ONLY} ]]
    then
        args=("$@")
        ini_file="${SOPHOS_TEMP_DIRECTORY}/thininstallerArgs.ini"
        for key in "${args[@]}"
        do
            (umask 0177 && echo "${key} = true" >> ${ini_file})
        done
    fi
}

function checkFunctionToStr
{
    func_name=${1}
    case $func_name in

      check_install_path_has_correct_permissions)
        echo -n "installPathHasCorrectPerms"
        ;;

      verify_install_directory)
        echo -n "installPathVerified"
        ;;

      verify_compatible_glibc_version)
        echo -n "glibcVersionVerified"
        ;;

      verify_installed_packages)
        echo -n "installedPackagesVerified"
        ;;

      check_free_storage)
        echo -n "sufficientDiskSpace"
        ;;

      verify_network_connections)
        echo -n "networkConnectionsVerified"
        ;;

      verify_all_possible_connections_to_cdn)
        echo -n "cdnConnectionVerified"
        ;;

      verify_all_possible_connections_to_sus)
        echo -n "susConnectionVerified"
        ;;

      verify_all_possible_connections_to_central)
        echo -n "centralConnectionVerified"
        ;;

      check_total_mem)
        echo -n "sufficientMemory"
        ;;

      check_ca_certs)
        echo -n "cacertsVerified"
        ;;

      verify_system_requirements)
        echo -n "systemRequirementsVerified"
        ;;

      pre_install_checks)
        echo -n "preInstallChecksPassed"
        ;;

      check_for_existing_spl_install)
        echo -n "splNotAlreadyInstalled"
        ;;

      test_installation_executable)
        echo -n "installationDirIsExecutable"
        ;;

      handle_register_errorcodes | register_central_with_previous_installation)
        echo -n "registrationWithCentral"
        ;;

      handle_installer_errorcodes)
        echo -n "productInstalled"
        ;;

      main)
        echo -n "thinInstallerSucceeded"
        ;;

    esac
}

function log_error() {
    func_name=${FUNCNAME[1]}
    [[ -n "$2" ]] && func_name="$2"
    check_performed=$(checkFunctionToStr ${func_name})
    write_check_result ${check_performed} "false"
    COMPATIBILITY_ERROR_FOUND=1
    [[ "${SUMMARY}" == "success" ]] && SUMMARY="${1}"
    echo "ERROR: ${SUMMARY}"
}

function success()
{
    check_performed=$(checkFunctionToStr ${FUNCNAME[1]})
    [[ -z ${COMPATIBILITY_ERROR_FOUND} ]] && write_check_result ${check_performed} "true"
}

function failure() {
    printf -v exit_date '%(%Y-%m-%d %H:%M:%S)T\n' -1
    echo "Handling failure on ${exit_date}"
    func_name=${FUNCNAME[1]}
    [[ -n "$3" ]] && func_name="$3"
    check_performed=$(checkFunctionToStr ${func_name})
    write_check_result ${check_performed} "false"
    if [[ "${SUMMARY}" != "success" ]]
    then
        write_check_result "summary" "${SUMMARY}"
    else
        write_check_result "summary" "$2"
    fi
    code=$1

    echo "$2" >&2

    # Log errors from SulDownloader
    if [[ -s "${SOPHOS_INSTALL}/logs/base/suldownloader.log" ]]
    then
        grep -E 'ERROR|FATAL' "${SOPHOS_INSTALL}/logs/base/suldownloader.log" | sed -E -e 's/.*(ERROR|FATAL).*>(.*)/\1\2/'
    fi

    # Dump logs which may be useful for support/developers to troubleshoot issues
    if [[ -n "${DEBUG_THIN_INSTALLER}" ]]
    then
        if [[ -s "${SOPHOS_INSTALL}/logs/base/suldownloader.log" ]]
        then
            echo "-- Output from ${SOPHOS_INSTALL}/logs/base/suldownloader.log:"
            cat "${SOPHOS_INSTALL}/logs/base/suldownloader.log"
        fi
        if [[ -s "${SOPHOS_INSTALL}/logs/base/suldownloader_sync.log" ]]
        then
            echo "-- Output from ${SOPHOS_INSTALL}/logs/base/suldownloader_sync.log:"
            cat "${SOPHOS_INSTALL}/logs/base/suldownloader_sync.log"
        fi
    fi

    # Only remove files if we created the install directory but didn't get far enough through the process to install (to
    # create the service files)
    if [[ $CREATED_INSTALL_DIRECTORY == 1 ]]
    then
        if is_sspl_installed
        then
            echo "Warning: the product has been partially installed and not all functionality may be present"
            echo "Logs are available at ${SOPHOS_INSTALL}/logs and ${SOPHOS_INSTALL}/plugins/*/log"
        else
            if [[ -d ${SOPHOS_TEMP_DIRECTORY} ]]; then
                echo "Copying SPL logs to ${SOPHOS_TEMP_DIRECTORY}/logs"
                cp -Lr "${SOPHOS_INSTALL}/logs" "${SOPHOS_TEMP_DIRECTORY}" 2>/dev/null
                mkdir -p "${SOPHOS_TEMP_DIRECTORY}/logs/plugins"
                cp -Lr "${SOPHOS_INSTALL}/plugins/*/log/*" "${SOPHOS_TEMP_DIRECTORY}/logs/plugins" 2>/dev/null
            fi
            echo "Removing ${SOPHOS_INSTALL}"
            # Try to uninstall base if we have its uninstaller
            if [[ -f "${SOPHOS_INSTALL}/bin/uninstall.sh" ]]
            then
                bash "${SOPHOS_INSTALL}/bin/uninstall.sh" --force
            elif [[ -f "${SOPHOS_INSTALL}/base/update/cache/sdds3primary/ServerProtectionLinux-Base-component/files/bin/uninstall.sh" ]]
            then
                bash "${SOPHOS_INSTALL}/base/update/cache/sdds3primary/ServerProtectionLinux-Base-component/files/bin/uninstall.sh" --force
            fi
            rm -rf "${SOPHOS_INSTALL}"
        fi
    fi

    echo "Please see https://docs.sophos.com/central/customer/help/en-us/index.html?contextId=protect-devices-server-Linux-agent-troubleshooting for troubleshooting help"

    cleanup_and_exit ${code}
}

function handle_installer_errorcodes() {
    errcode=$1

    if [[ ${errcode} -eq 0 ]]; then
        printf -v FINISHED_DATE '%(%Y-%m-%d %H:%M:%S)T\n' -1
        echo  "Successfully installed product on ${FINISHED_DATE}"
        success
    elif [[ ${errcode} -eq 103 ]]; then
        failure ${EXITCODE_BASE_INSTALL_FAILED} "Failed to install at least one of the packages, see logs for details"
    elif [[ ${errcode} -eq 107 ]]; then
        failure ${EXITCODE_BASE_INSTALL_FAILED} "Failed to install: Download failure"
    elif [[ ${errcode} -eq 111 ]]; then
        failure ${EXITCODE_BASE_INSTALL_FAILED} "Failed to install: Package source missing from repository"
    elif [[ ${errcode} -eq 112 ]]; then
        failure ${EXITCODE_BASE_INSTALL_FAILED} "Failed to install: Connection error - please check your network connections"
    else
        failure ${EXITCODE_BASE_INSTALL_FAILED} "Failed to install (Error code = ${errcode})"
    fi
}

function handle_register_errorcodes() {
    errcode=$1
    if [[ ${errcode} -eq 0 ]]; then
        echo "Successfully registered with Sophos Central"
        success
    elif [[ ${errcode} -eq 44 ]]; then
        failure ${EXITCODE_NO_CENTRAL} "Cannot connect to Sophos Central - please check your network connections"
    elif [[ ${errcode} -eq ${EXITCODE_REGISTRATION_FAILED} ]]; then # Error code 51
        failure ${EXITCODE_REGISTRATION_FAILED} "Failed to register with Sophos Central, aborting installation"
    elif [[ ${errcode} -eq ${EXITCODE_AUTHENTICATION_FAILED} ]]; then # Error code 52
        failure ${EXITCODE_AUTHENTICATION_FAILED} "Failed to authenticate with Sophos Central, aborting installation"
    elif [[ ${errcode} -eq ${EXIT_CODE_TAEGIS_TENANT_ID_MISTMATCH} ]]; then # Error code 58
        failure ${EXIT_CODE_TAEGIS_TENANT_ID_MISTMATCH} "Local Taegis tenant ID does not match central Taegis tenant ID"
    else
        failure ${EXITCODE_DOWNLOAD_FAILED} "Failed to register with Central (Error code = ${errcode})"
    fi
}

#
# Use mktemp if it is available, or try to create unique
# directory name and use mkdir instead.
#
# Pass directory name prefix as a parameter.
#
function sophos_mktempdir() {
    _mktemp=$(which mktemp 2>/dev/null)
    if [ -x "${_mktemp}" ]; then
        # mktemp exists - use it
        _tmpdirTemplate="${TMPDIR:-/tmp}/$1_XXXXXXX"
        _tmpdir=$(${_mktemp} -d "${_tmpdirTemplate}")
        [ $? = 0 ] || {
            echo "Could not create temporary directory" 1>&2
            exit 1
        }
    else
        _od=$(which od 2>/dev/null)
        if [ -x "${_od}" ]; then
            # mktemp not available - use /dev/urandom, od and mkdir
            _random=/dev/urandom
            [ -f "${_random}" ] || _random=/dev/random
            _tmpdir="${TMPDIR:-/tmp}"/$1_$("${_od}" -An -N16 -tu2 "${_random}" | tr -d " \t\r\n").$$
        else
            # mktemp not available - /dev/urandom not available - use $RANDOM and mkdir
            _tmpdir="${TMPDIR:-/tmp}"/$1_${RANDOM-0}.${RANDOM-0}.${RANDOM-0}.$$
        fi
        [ -d "${_tmpdir}" ] && {
            echo "Temporary directory already exists" 1>&2
            exit 1
        }
        (umask 077 && mkdir "${_tmpdir}") || {
            echo "Could not create temporary directory" 1>&2
            exit 1
        }
    fi

    if [ ! -d "${_tmpdir}" ]; then
        echo "Could not create temporary directory" 1>&2
        exit ${EXITCODE_CANNOT_MAKE_TEMP}
    fi

    echo "${_tmpdir}"
}

function check_for_duplicate_arguments() {
    declare -a checked_arguments
    for argument in "$@"; do
        argument_name="${argument%=*}"
        [[ "${checked_arguments[@]}" =~ (^| )"$argument_name"($| ) ]] && failure ${EXITCODE_DUPLICATE_ARGUMENTS_GIVEN} "Error: Duplicate argument given: $argument_name --- aborting install"
        checked_arguments+=("$argument_name")
    done
}

function validate_group_name() {
    [ -z "$1" ] && failure ${EXITCODE_BAD_GROUP_NAME} "Error: Group name not passed with '--group=' argument --- aborting install"
    [[ ${#1} -gt ${MAX_GROUP_NAME_SIZE} ]] && failure ${EXITCODE_GROUP_NAME_EXCEEDS_MAX_SIZE} "Error: Group name exceeds max size of: ${MAX_GROUP_NAME_SIZE} --- aborting install"
    is_string_valid_for_xml "$1" || failure ${EXITCODE_BAD_GROUP_NAME} "Error: Group name contains one of the following invalid characters: < & > ' \" --- aborting install"
}

function validate_memory_percentage() {
    [ -z "$1" ] && failure ${EXITCODE_ABSENT_MEMORY_PERCENTAGE} "Error: Memory percentage not passed with '--memory-limit=' argument --- aborting install"
    case $1 in
        ''|*[!0-9]*) failure ${EXITCODE_BAD_CGROUP_LIMIT_PERCENTAGE} "Error: Memory percentage is not strictly comprised of digits --- aborting install";;
        *) ;;
    esac

    if (("$1" < 1 || "$1" > 100)); then
      failure ${EXITCODE_BAD_CGROUP_LIMIT_PERCENTAGE} "Error: Memory percentage outside of range [1, 100] passed with '--memory-limit=' argument --- aborting install"
    fi
    percentage=$1
    phymem=$(LANG=C free | awk '/^Mem:/{print $2}')
    desired_memory=$(((phymem * percentage) / 100))
    if (("$desired_memory" < 2000000)); then
      failure ${EXITCODE_INSUFFICENT_MEMORY_PERCENTAGE_LIMIT} "Error: Passed memory percentage yields memory limit below 2GB --- aborting install"
    fi
}

function validate_cpu_percentage() {
    [ -z "$1" ] && failure ${EXITCODE_ABSENT_CPU_PERCENTAGE} "Error: CPU percentage not passed with '--cpu-limit=' argument --- aborting install"
    case $1 in
        ''|*[!0-9]*) failure ${EXITCODE_BAD_CGROUP_LIMIT_PERCENTAGE} "Error: CPU percentage is not strictly comprised of digits --- aborting install";;
        *) ;;
    esac
    if (("$1" < 1 || "$1" > 100)); then
      failure ${EXITCODE_BAD_CGROUP_LIMIT_PERCENTAGE} "Error: CPU percentage outside of range [1, 100] passed with '--cpu-limit=' argument --- aborting install"
    fi
}

function is_string_valid_for_xml() {
    [[ ! $1 =~ .*[\>\<\&\'\"].* ]]
}

function check_selected_products_are_valid() {
    local products="${1}"
    [[ "${products: -1}" == "," ]] && failure ${EXITCODE_BAD_PRODUCT_SELECTED} "Error: Products passed with trailing comma --- aborting install"
    [[ "${products}" == "${REQUEST_NO_PRODUCTS}" ]] && return 0
    [[ -n "${products}" && "${products}" != " " ]] || failure ${EXITCODE_BAD_PRODUCT_SELECTED} "Error: Products not passed with '--products=' argument --- aborting install"
    declare -a selected_products
    IFS=',' read -ra PRODUCTS_ARRAY <<<"${products}"
    [[ -n "${PRODUCTS_ARRAY}" && "$PRODUCTS_ARRAY" != " " ]] || failure ${EXITCODE_BAD_PRODUCT_SELECTED} "Error: Products not passed with '--products=' argument --- aborting install"
    for product in "${PRODUCTS_ARRAY[@]}"; do
        [[ -n "${product}" && "${product}" != " " ]] || failure ${EXITCODE_BAD_PRODUCT_SELECTED} "Error: Product cannot be whitespace"
        [[ ! "${VALID_PRODUCTS[*]}" =~ (^| )"${product}"($| ) ]] && failure ${EXITCODE_BAD_PRODUCT_SELECTED} "Error: Invalid product selected: ${product} --- aborting install."
        [[ "${selected_products[*]}" =~ (^| )"${product}"($| ) ]] && failure ${EXITCODE_BAD_PRODUCT_SELECTED} "Error: Duplicate product given: ${product} --- aborting install."
        selected_products+=("${product}")
    done
}

function validate_MR_and_UC_addresses() {
    local addresses="${1}"
    local server_type="${2}"

    [[ "${addresses: -1}" == "," ]] && failure ${EXITCODE_INVALID_MR_UC_GIVEN} "Error: ${server_type}s passed with trailing comma --- aborting install"
    [[ -n "${addresses}" && "${addresses}" != " " ]] || failure ${EXITCODE_INVALID_MR_UC_GIVEN} "Error: ${server_type}s not passed with '--${server_type/ /-}s=' argument --- aborting install"

    declare -a valid_addresses
    IFS=',' read -ra ADDRESS_ARRAY <<<"${addresses}"
    [[ -n "${ADDRESS_ARRAY}" && "${ADDRESS_ARRAY}" != " " ]] || failure ${EXITCODE_INVALID_MR_UC_GIVEN} "Error: ${server_type}s not passed with '--${server_type/ /-}s=' argument --- aborting install"
    for address in "${ADDRESS_ARRAY[@]}"; do
        [[ -n "${address}" && "${address}" != " " ]] || failure ${EXITCODE_INVALID_MR_UC_GIVEN} "Error: ${server_type} cannot be whitespace"
        [[ "${address}" =~ ^[a-zA-Z0-9._-]+:[0-9]+$ ]] || failure ${EXITCODE_INVALID_MR_UC_GIVEN} "Error: Requested ${server_type} address not valid: ${address} --- aborting install"
        [[ "${valid_addresses[*]}" =~ (^| )"${address}"($| ) ]] && failure ${EXITCODE_INVALID_MR_UC_GIVEN} "Error: Duplicate ${server_type} given: ${address} --- aborting install."
        valid_addresses+=("${address}")
    done
}

function check_custom_ids_are_valid() {
    local ids="${1}"

    [[ "${ids: -1}" == "," ]] && failure ${EXITCODE_INVALID_CUSTOM_ID_GIVEN} "Error: Requested group/user ids to configure passed with trailing comma --- aborting install"
    [[ -n "${ids}" && "${ids}" != " " ]] || failure ${EXITCODE_INVALID_CUSTOM_ID_GIVEN} "Error: Requested group/user ids to configure not passed with argument --- aborting install"

    declare -a valid_ids
    IFS=',' read -ra IDS_ARRAY <<<"${ids}"
    [[ -n "${IDS_ARRAY}" && "${IDS_ARRAY}" != " " ]] || failure ${EXITCODE_INVALID_CUSTOM_ID_GIVEN} "Error: Requested group/user ids to configure not passed with argument --- aborting install"
    for id in "${IDS_ARRAY[@]}"; do
        [[ -n "${id}" && "${id}" != " " ]] || failure ${EXITCODE_INVALID_CUSTOM_ID_GIVEN} "Error: Requested ID cannot contain whitespace: ${id}  --- aborting install"
        [[ "${id}" =~ ^sophos-spl-?(.*):[0-9]+$ ]] || failure ${EXITCODE_INVALID_CUSTOM_ID_GIVEN} "Error: Requested group/user id to configure is not valid: ${id} --- aborting install"
        [[ "${valid_ids[*]%%:*}" =~ (^| )"${id%%:*}"($| ) ]] && failure ${EXITCODE_INVALID_CUSTOM_ID_GIVEN} "Error: Duplicate user name given: ${id} --- aborting install"
        [[ "${valid_ids[*]#*:}" =~ (^| )"${id#*:}"($| ) ]] && failure ${EXITCODE_INVALID_CUSTOM_ID_GIVEN} "Error: Duplicate id given: ${id} --- aborting install"
        valid_ids+=("${id}")
    done
}

function pre_install_checks() {
    echo -e "\nPerforming pre-installation checks to verify whether SPL can be installed on this machine"

    # Check running as root
    [[ $(id -u) -ne 0 ]] && failure ${EXITCODE_NOT_ROOT} "Please run this installer as root"

    # Check have necessary binaries to carry out install
    verify_necessary_binaries

    # Run common SPL compatibility checks
    verify_system_requirements

    # Get baked in Central URL and any configured Message Relays/Update Caches
    CENTRAL_URL=$(sed -n -e "/^URL=/ s/.*\= *//p" "${INSTALL_FILE}")

    if [[ "${MESSAGE_RELAYS_OVERRIDE}" != "none" ]]; then
        if [[ -n "${MESSAGE_RELAYS_OVERRIDE}" ]]; then
          message_relays="${MESSAGE_RELAYS_OVERRIDE}"
          IFS=',' read -ra message_relay_array <<<"${message_relays}"
        else
          message_relays="$(sed -n -e "/^MESSAGE_RELAYS=[^$]/ s/.*\= *//p" "${INSTALL_FILE}")"
          IFS=';' read -ra message_relay_array <<<"${message_relays}"
        fi
        for message_relay in "${message_relay_array[@]}"; do
            MESSAGE_RELAYS+=("${message_relay%%,*}")
        done
    fi

    if [[ "${UPDATE_CACHES_OVERRIDE}" != "none" ]]; then
        if [[ -n "${UPDATE_CACHES_OVERRIDE}" ]]; then
          update_caches="${UPDATE_CACHES_OVERRIDE}"
          IFS=',' read -ra update_cache_array <<<"${update_caches}"
        else
          update_caches="$(sed -n -e "/^UPDATE_CACHES=[^$]/ s/.*\= *//p" "${INSTALL_FILE}")"
          IFS=';' read -ra update_cache_array <<<"${update_caches}"
        fi
        for update_cache in "${update_cache_array[@]}"; do
            UPDATE_CACHES+=("${update_cache%%,*}")
        done
    fi

    # Read SDDS3 SUS URL from credentials file, e.g. SDDS3_SUS_URL=sus.sophosupd.com
    EXTRACTED_SUS_URL=$(sed -n -e "/^SDDS3_SUS_URL=/ s/.*\= *//p" "${INSTALL_FILE}")
    if [[ "$EXTRACTED_SUS_URL" != "" && $EXTRACTED_SUS_URL != https://* ]]
    then
        EXTRACTED_SUS_URL="https://${EXTRACTED_SUS_URL}"
    fi
    # Read SDDS3 CDN URLs from credentials file, e.g. SDDS3_CONTENT_URLS=sdds3.sophosupd.com;sdds3.sophosupd.net
    cdn_urls="$(sed -n -e "/^SDDS3_CONTENT_URLS=[^$]/ s/.*\= *//p" "${INSTALL_FILE}")"
    IFS=';' read -ra cdn_urls_array <<<"${cdn_urls}"
    for cdn_url in "${cdn_urls_array[@]}"; do
         if [[ $cdn_url != https://* ]]
        then
            cdn_url="https://${cdn_url}"
        fi
        EXTRACTED_CDN_URLS+=("${cdn_url%%,*}")
    done

    # Verify network connections made during installation to Central, SUS and CDN servers
    verify_network_connections "${MESSAGE_RELAYS[*]}" "${UPDATE_CACHES[*]}" "${EXTRACTED_CDN_URLS[*]}" "$EXTRACTED_SUS_URL"

    if [[ -n "${COMPATIBILITY_ERROR_FOUND}" ]]; then
        failure ${EXITCODE_COMPATIBILITY_CHECKS_FAILED} "SPL cannot be installed on this system, the pre-installation checks found some critical issues. Please review the logs and address the issues before attempting to reinstall"
    elif [[ -n "${COMPATIBILITY_WARNING_FOUND}" ]]; then
        echo "SPL can be installed on this system, however, the pre-installation checks found some non-critical issues. Please review and address these"
    else
        echo "SPL can be installed on this system based on the pre-installation checks"
    fi
    echo
}

function make_tmp_dir()
{
    # Create Sophos temp directory (unless overridden with an existing dir)
    if [ -z "${SOPHOS_TEMP_DIRECTORY}" ]; then
        export SOPHOS_TEMP_DIRECTORY=$(sophos_mktempdir SophosCentralInstall) || failure ${EXITCODE_CANNOT_MAKE_TEMP} "Could not generate name for temp directory in ${TMPDIR:-/tmp}"
    fi

    mkdir -p "${SOPHOS_TEMP_DIRECTORY}"
}

function register_central_with_previous_installation()
{
  if [[ -d "${SOPHOS_INSTALL}" ]]
  then
      if [[ -f "$REGISTER_CENTRAL" ]]
      then
          echo "Attempting to register existing installation with Sophos Central"
          echo "Central token is [$CLOUD_TOKEN], Central URL is [$CLOUD_URL]"

          ${REGISTER_CENTRAL} "${CLOUD_TOKEN}" ${CLOUD_URL} ${MESSAGE_RELAYS} $PRODUCT_ARGUMENTS $CUSTOMER_TOKEN_ARGUMENT
          if [[ $? -ne 0 ]]
          then
              failure ${EXITCODE_FAILED_REGISTER} "ERROR: Failed to register with Sophos Central with previous existing installation $?"
          fi
          write_check_result "summary" "successfully re-registered existing installation"
          cleanup_and_exit ${EXITCODE_SUCCESS}
      else
          echo "Existing installation failed validation and will be reinstalled"
      fi
  fi
}

declare -a INSTALL_OPTIONS_ARGS
declare -a ARGS_FOR_TELEMETRY
# Handle arguments
check_for_duplicate_arguments "$@"
FORCE_INSTALL=0
UNEXPECTED_ARGUMENT=0
HELP_FLAG=0
VERSION_FLAG=0
SKIP_TAEGIS_TENANT_ID_CHECK=""
UNINSTALL_TAEGIS=1
UNINSTALL_REDCLOAK=1

for i in "$@"; do
    key=${i#"--"}
    ARGS_FOR_TELEMETRY+=("${key%=*}")
    case $i in
    --install-dir=*)
        SOPHOS_INSTALL="${i#*=}"
        shift
        ;;
    --update-source-creds=*)
        export OVERRIDE_SOPHOS_CREDS="${i#*=}"
        shift
        ;;
    --proxy-credentials=*)
        export PROXY_CREDENTIALS="${i#*=}"
        ;;
    --products=*)
        check_selected_products_are_valid "${i#*=}"
        PRODUCT_ARGUMENTS="--products ${i#*=}"
        CMCSROUTER_PRODUCT_ARGUMENTS="${i}"
        shift
        ;;
    --allow-override-mcs-ca)
        export ALLOW_OVERRIDE_MCS_CA=--allow-override-mcs-ca
        shift
        ;;
    --group=*)
        validate_group_name "${i#*=}"
        REGISTRATION_GROUP_ARGS="--central-group=${i#*=}"
        INSTALL_OPTIONS_ARGS+=("$i")
        shift
        ;;
    --user-ids-to-configure=*)
        check_custom_ids_are_valid "${i#*=}"
        INSTALL_OPTIONS_ARGS+=("$i")
        shift
        ;;
    --group-ids-to-configure=*)
        check_custom_ids_are_valid "${i#*=}"
        INSTALL_OPTIONS_ARGS+=("$i")
        shift
        ;;
    --message-relays=*)
        [[ "${i#*=}" == "none" ]] || validate_MR_and_UC_addresses "${i#*=}" "message relay"
        MESSAGE_RELAYS_OVERRIDE="${i#*=}"
        shift
        ;;
    --update-caches=*)
        [[ "${i#*=}" == "none" ]] || validate_MR_and_UC_addresses "${i#*=}" "update cache"
        export UPDATE_CACHES_OVERRIDE="${i#*=}"
        shift
        ;;
    --override-hostname=*)
        HOSTNAME_OVERRIDE="${i#*=}"
        shift
        ;;
    --force)
        FORCE_INSTALL=1
        shift
        ;;
    --test)
        echo "Found '--test' is used, will only do pre-install checks and will not install SPL"
        PRE_INSTALL_TEST_ONLY=1
        ;;
    --notest)
        echo "Found '--notest' is used, will not perform pre-install checks but will proceed with installing SPL"
        NO_PRE_INSTALL_TESTS=1
        ;;
    --memory-limit=*)
        validate_memory_percentage "${i#*=}"
        INSTALL_OPTIONS_ARGS+=("$i")
        shift
        ;;
    --cpu-limit=*)
        validate_cpu_percentage "${i#*=}"
        INSTALL_OPTIONS_ARGS+=("$i")
        shift
        ;;
    --help|-h)
        HELP_FLAG=1
        ;;
    --version|-v)
        VERSION_FLAG=1
        ;;
    --skip-taegis-tenant-id-check)
        SKIP_TAEGIS_TENANT_ID_CHECK="--skip-taegis-tenant-id-check"
        ;;
    --skip-taegis-uninstall)
        UNINSTALL_TAEGIS=0
        ;;
    --skip-redcloak-uninstall)
        UNINSTALL_REDCLOAK=0
        ;;
    *)
        UNEXPECTED_ARGUMENT=1
        UNEXPECTED_ARG_VAL=$i
        ;;
    esac
done

if [[ ${HELP_FLAG} == 1 ]]
then
    get_help_text
    exit 0
fi

if [[ ${VERSION_FLAG} == 1 ]]
then
    echo "${PRODUCT_NAME} Installer, version: $VERSION"
    exit 0
fi

if [[ ${UNEXPECTED_ARGUMENT} == 1 ]]
then
  failure ${EXITCODE_UNEXPECTED_ARGUMENT} "Error: Unexpected argument given: $UNEXPECTED_ARG_VAL --- aborting install. Please see '--help' output for list of valid arguments"
fi

printf -v start_date '%(%Y-%m-%d %H:%M:%S)T\n' -1
echo "Starting Install on ${start_date}"

make_tmp_dir
CREDENTIALS_FILE_PATH=${SOPHOS_TEMP_DIRECTORY}/credentials.txt

write_args_to_file "${ARGS_FOR_TELEMETRY[@]}"
if [[ ${NO_PRE_INSTALL_TESTS} != 1 ]]
then
    pre_install_checks
else
    # Check machine architecture
    if [[ $(uname -m) = "x86_64" || $(uname -m) = "aarch64" ]]
    then
        BIN="bin"
    else
        failure ${EXITCODE_NOT_64_BIT} "ERROR: SPL installation will fail as it can only be installed on a x86_64 or aarch64 system"
    fi
fi

verify_install_directory

# Check that the tmp directory we're using allows execution
echo "exit 0" >"${SOPHOS_TEMP_DIRECTORY}/exectest" 2>/dev/null && chmod +x "${SOPHOS_TEMP_DIRECTORY}/exectest"
$SOPHOS_TEMP_DIRECTORY/exectest 2>/dev/null \
  || failure ${EXITCODE_NOEXEC_TMP} "Cannot execute files within ${TMPDIR:-/tmp} directory. Please ensure ${TMPDIR:-/tmp} is not mounted with noexec option."

function test_installation_executable()
{
    # Don't attempt execution test if install dir already exists
    [[ -d "$SOPHOS_INSTALL" ]] && return
    # ensure parent directories of install dir have the correct permissions by setting umask
    umask 066
    mkdir -p "$SOPHOS_INSTALL"
    umask 077
    echo "exit 0" >"${SOPHOS_INSTALL}/exectest" 2>/dev/null && chmod +x "${SOPHOS_INSTALL}/exectest"
    $SOPHOS_INSTALL/exectest 2>/dev/null || {
      rm -r "$SOPHOS_INSTALL"
      failure ${EXITCODE_NOEXEC_TMP} "Cannot execute files within ${SOPHOS_INSTALL} directory. Please ensure the mount point for ${SOPHOS_INSTALL} is not mounted with noexec option."
    }
    rm -r "$SOPHOS_INSTALL"
    success
}

function check_for_existing_spl_install()
{
    # Check we have found the path for the existing installation.
    if [ ! -d "$EXISTING_SSPL_PATH" ]; then
        failure ${EXITCODE_INSTALLED_BUT_NO_PATH} "An existing installation of ${PRODUCT_NAME} was found but could not find the installed path. You could try 'SophosSetup.sh --force' to force the install"
    fi
    success
}

test_installation_executable

if [[ -n ${PRE_INSTALL_TEST_ONLY} ]]
then
    cleanup_and_exit ${EXITCODE_SUCCESS}
fi

echo "Installing to ${SOPHOS_INSTALL}"

# Check to see if the Sophos credentials override is being used.
[ -n "$OVERRIDE_SOPHOS_CREDS" ] && {
    echo "Overriding Sophos credentials with $OVERRIDE_SOPHOS_CREDS"
}

# Get line numbers for the each of the sections
MIDDLEBIT=$(awk '/^__MIDDLE_BIT__/ {print NR + 1; exit 0; }' "${INSTALL_FILE}")
UC_CERTS=$(awk '/^__UPDATE_CACHE_CERTS__/ {print NR + 1; exit 0; }' "${INSTALL_FILE}")
ARCHIVE=$(awk '/^__ARCHIVE_BELOW__/ {print NR + 1; exit 0; }' "${INSTALL_FILE}")

if [[ -z "${MIDDLEBIT}" ]]; then
  failure ${EXITCODE_MALFORMED_THININSTALLER} "Thin installer is malformed it is missing the __MIDDLE_BIT__ seperator."
fi

# If we have __UPDATE_CACHE_CERTS__ section then the middle section ends there, else it ends at the ARCHIVE marker.
if [[ -n "${UC_CERTS}" ]]; then
    mkdir -p "${SOPHOS_TEMP_DIRECTORY}/installer"
    UPDATE_CACHE_CERT="${SOPHOS_TEMP_DIRECTORY}/installer/uc_certs.crt"
    MIDDLEBIT_SIZE=$((UC_CERTS - MIDDLEBIT - 1))
    UC_CERTS_SIZE=$((ARCHIVE - UC_CERTS - 1))
    tail -n+"${UC_CERTS}" "${INSTALL_FILE}" | head -"${UC_CERTS_SIZE}" | tr -d '\r' | tr -s '\n' >"${UPDATE_CACHE_CERT}"
else
    MIDDLEBIT_SIZE=$((ARCHIVE - MIDDLEBIT - 1))
fi

tail -n+"${MIDDLEBIT}" "${INSTALL_FILE}" | head -"${MIDDLEBIT_SIZE}" >"${CREDENTIALS_FILE_PATH}"

if [[ $(uname -m) = "x86_64" ]]; then
  sed -n -e '/^__ARCHIVE_BELOW__$/,/^__ARM64_ARCHIVE_BELOW__$/{ /^__ARCHIVE_BELOW__$/d; /^__ARM64_ARCHIVE_BELOW__$/d; p; }' "${INSTALL_FILE}" > ${SOPHOS_TEMP_DIRECTORY}/installer.tar.gz
  truncate -s -1 ${SOPHOS_TEMP_DIRECTORY}/installer.tar.gz
elif [[ $(uname -m) = "aarch64" ]]; then
  sed -n -e '/^__ARM64_ARCHIVE_BELOW__$/,/^__ARM64_ARCHIVE_ABOVE__$/{ /^__ARM64_ARCHIVE_BELOW__$/d; /^__ARM64_ARCHIVE_ABOVE__$/d; p; }' "${INSTALL_FILE}" > ${SOPHOS_TEMP_DIRECTORY}/installer.tar.gz
  truncate -s -1 ${SOPHOS_TEMP_DIRECTORY}/installer.tar.gz
fi

# Adjust Message Relays and Update Caches in credentials file based on override arguments
if [[ "${MESSAGE_RELAYS_OVERRIDE}" == "none" ]]; then
    echo "Message relay manually set to none, installation will not be performed via a message relay"
    modifiedCreds="$(grep -v "MESSAGE_RELAYS=" "${CREDENTIALS_FILE_PATH}")"
    echo "${modifiedCreds}" >"${CREDENTIALS_FILE_PATH}"
elif [[ -n "${MESSAGE_RELAYS_OVERRIDE}" ]]; then
    MESSAGE_RELAYS_OVERRIDE="${MESSAGE_RELAYS_OVERRIDE//,/,0,overridden-message-relay;},0,overridden-message-relay"
    modifiedCreds="$(grep -v "MESSAGE_RELAYS=" "${CREDENTIALS_FILE_PATH}")"
    echo "${modifiedCreds}" >"${CREDENTIALS_FILE_PATH}"
    echo -n "MESSAGE_RELAYS=${MESSAGE_RELAYS_OVERRIDE}" >>"${CREDENTIALS_FILE_PATH}"
fi
if [[ "${UPDATE_CACHES_OVERRIDE}" == "none" ]]; then
    echo "Update cache manually set to none, updates will not be performed via an update cache"
    modifiedCreds="$(grep -v "UPDATE_CACHES=" "${CREDENTIALS_FILE_PATH}")"
    echo "${modifiedCreds}" >"${CREDENTIALS_FILE_PATH}"
elif [[ -n "${UPDATE_CACHES_OVERRIDE}" ]]; then
    UPDATE_CACHES_OVERRIDE="${UPDATE_CACHES_OVERRIDE//,/,0,overridden-update-cache;},0,overridden-update-cache"
    modifiedCreds="$(grep -v "UPDATE_CACHES=" "${CREDENTIALS_FILE_PATH}")"
    echo "${modifiedCreds}" >"${CREDENTIALS_FILE_PATH}"
    echo -n "UPDATE_CACHES=${UPDATE_CACHES_OVERRIDE}" >>"${CREDENTIALS_FILE_PATH}"
fi

cd ${SOPHOS_TEMP_DIRECTORY}

# Read customer token from credentials file.
if [ -z "${OVERRIDE_CUSTOMER_TOKEN}" ]; then
    CUSTOMER_TOKEN=$(grep 'CUSTOMER_TOKEN=' credentials.txt | sed 's/CUSTOMER_TOKEN=//')
else
    CUSTOMER_TOKEN=${OVERRIDE_CUSTOMER_TOKEN}
fi
CUSTOMER_TOKEN_ARGUMENT="--customer-token $CUSTOMER_TOKEN"

# Read cloud token from credentials file.
if [ -z "${OVERRIDE_CLOUD_TOKEN}" ]; then
    CLOUD_TOKEN=$(grep -v 'CUSTOMER_TOKEN=' credentials.txt | grep 'TOKEN=' | sed 's/TOKEN=//')
else
    CLOUD_TOKEN=${OVERRIDE_CLOUD_TOKEN}
fi

# Read cloud URL from credentials file.
if [ -z "${OVERRIDE_CLOUD_URL}" ]; then
    CLOUD_URL=$(grep '^URL=' credentials.txt | sed 's/URL=//')
else
    CLOUD_URL=${OVERRIDE_CLOUD_URL}
fi

# Read Message Relays from credentials file.
MESSAGE_RELAYS=$(grep 'MESSAGE_RELAYS=' credentials.txt | sed 's/MESSAGE_RELAYS=//')
if [[ -n "${MESSAGE_RELAYS}" ]]; then
    [[ -n "$DEBUG_THIN_INSTALLER" ]] && echo "Message Relays: ${MESSAGE_RELAYS}"
    CMCSROUTER_MESSAGE_RELAYS="--message-relay ${MESSAGE_RELAYS}"
    MESSAGE_RELAYS="--messagerelay ${MESSAGE_RELAYS}"
fi

# Save installer arguments to file for base and plugins to use.
INSTALL_OPTIONS_FILE="${SOPHOS_TEMP_DIRECTORY}/install_options"

# File format expects the args to be either --option  or --option=value
for value in "${INSTALL_OPTIONS_ARGS[@]}"; do
    echo $value >>${INSTALL_OPTIONS_FILE}
done

UPDATE_CACHES=$(grep 'UPDATE_CACHES=' credentials.txt | sed 's/UPDATE_CACHES=//')
if [[ -n "${UPDATE_CACHES}" ]]; then
    if [[ -n "${DEBUG_THIN_INSTALLER}" ]]; then
        echo "List of update caches to install from: ${UPDATE_CACHES}"
    fi
fi

# Read Products from credentials file if the customer has not used the installer option.
INSTALLER_PRODUCTS=$(grep 'PRODUCTS=' credentials.txt | sed 's/PRODUCTS=//')
if [ -n "$INSTALLER_PRODUCTS" ] && [ -z "$PRODUCT_ARGUMENTS" ] && [ "$INSTALLER_PRODUCTS" != "all" ]; then
    PRODUCT_ARGUMENTS="$INSTALLER_PRODUCTS"
    CMCSROUTER_PRODUCT_ARGUMENTS=$(grep 'PRODUCTS=' credentials.txt | sed 's/PRODUCTS=/--products=/')
    if [ -n "$DEBUG_THIN_INSTALLER" ]; then
        echo "List of products to install: $PRODUCT_ARGUMENTS"
    fi
fi

REGISTER_CENTRAL="${SOPHOS_INSTALL}/base/bin/registerCentral"

# Check if the sophos-spl service is installed, if it is find the install path.
EXISTING_SSPL_PATH=

if [ ${FORCE_INSTALL} -eq 1 ]; then
    echo "Forcing install"

    # Stop any possibly running services - may have a broken install and be wanting a re-install.
    systemctl stop sophos-spl 2>/dev/null
elif is_sspl_installed; then
    sspl_env=$(systemctl show -p Environment sophos-spl)
    sspl_env=${sspl_env#Environment=}
    for e in ${sspl_env}; do
        if [[ ${e%%=*} == "SOPHOS_INSTALL" ]]; then
            EXISTING_SSPL_PATH=${e#*=}
            echo "Found existing installation here: $EXISTING_SSPL_PATH"
            break
        fi
    done

    check_for_existing_spl_install

    # If the user specified a different install dir to the existing one then they must remove the old install first.
    if [[ "${SOPHOS_INSTALL}" != "${EXISTING_SSPL_PATH}" ]]; then
        failure ${EXITCODE_ALREADY_INSTALLED} "Please uninstall ${PRODUCT_NAME} before using this installer. You can run ${EXISTING_SSPL_PATH}/bin/uninstall.sh"
    fi

    # Check the existing installation is ok, if it is then register again with the creds from this installer.
    register_central_with_previous_installation
fi

echo "Installation process for ${PRODUCT_NAME} started"
MCS_TOKEN="$CLOUD_TOKEN"
MCS_URL="$CLOUD_URL"

# Any created directories need to be executable so that our non-root processes can go through them
umask 066
mkdir -p "${SOPHOS_INSTALL}/base/etc/sophosspl"
CREATED_INSTALL_DIRECTORY=1
umask 077

if [[ -n "$SOPHOS_LOG_LEVEL" ]]; then
    cat <<EOF >"${SOPHOS_INSTALL}/base/etc/logger.conf"
[global]
VERBOSITY = $SOPHOS_LOG_LEVEL
EOF
else
    cat <<EOF >"${SOPHOS_INSTALL}/base/etc/logger.conf"
[global]
VERBOSITY = INFO
EOF
fi

if [[ -n "$DEBUG_THIN_INSTALLER" ]]; then
    echo "[suldownloader]" >>"${SOPHOS_INSTALL}/base/etc/logger.conf"
    echo "VERBOSITY = DEBUG" >>"${SOPHOS_INSTALL}/base/etc/logger.conf"
fi

# Check to see if the computer hostname override is being used
if [[ -n "$HOSTNAME_OVERRIDE" ]]; then
    if [[ ${#HOSTNAME_OVERRIDE} -gt 256 ]]; then
        HOSTNAME_OVERRIDE=${HOSTNAME_OVERRIDE:0:256}
    fi
    echo "Overriding hostname with $HOSTNAME_OVERRIDE"
    echo -n "$HOSTNAME_OVERRIDE" > "${SOPHOS_INSTALL}/base/etc/hostname_override.conf"
fi
# Avoid new-line at end of file
echo -n $(hostname -f) >${SOPHOS_TEMP_DIRECTORY}/SOPHOS_HOSTNAME_F
export SOPHOS_HOSTNAME_F=${SOPHOS_TEMP_DIRECTORY}/SOPHOS_HOSTNAME_F

tar -zxf installer.tar.gz || failure ${EXITCODE_FAILED_TO_UNPACK} "ERROR: Failed to unpack thin installer: $?"
rm -f installer.tar.gz || failure ${EXITCODE_DELETE_INSTALLER_ARCHIVE_FAILED} "ERROR: Failed to delete packed thin installer: $?"

TAEGIS_CONF="/etc/taegis-agent.conf"
TAEGIS_TENANT_ID=""
TAEGIS_HOST_ID=""
if [[ -f "$TAEGIS_CONF" && "$(stat $TAEGIS_CONF --format="%U:%G %a")" == "root:root 644" ]]
then
    # Fetch Taegis installation directory (value of TAEGIS_AGENT_HOME)
    source "$TAEGIS_CONF"
    TAEGIS_STATUS="${TAEGIS_AGENT_HOME}/var/status/identstatus"
    if [[ -n "$TAEGIS_AGENT_HOME" && -f "$TAEGIS_STATUS" ]]
    then
        # Fetch Tenant ID and Host Id from Taegis status
        source "${TAEGIS_STATUS}"
        
        if [[ -n "${tenant_id}" ]] 
        then
            echo "Taegis Tenant ID: ${tenant_id}"
            TAEGIS_TENANT_ID="--taegis-tenant-id=${tenant_id}"
        else
            echo "Error fetching Taegis Tenant ID" >&2
        fi
        
        if [[ -n "${host_id}" ]]
        then
            echo "Taegis Host ID: ${host_id}"
            TAEGIS_HOST_ID="--taegis-host-id=${host_id}"
        else
            echo "Error fetching Taegis Host ID" >&2
        fi
    else
        echo "Error finding Taegis installation directory from $TAEGIS_CONF" >&2
    fi
    TAEGIS_INSTALLED=1
else
    UNINSTALL_TAEGIS=0
    TAEGIS_INSTALLED=0
fi

REDCLOAK_CONF="/etc/redcloak.conf"
REDCLOAK_DOMAIN_ID=""
REDCLOAK_AGENT_ID=""
# File exists and permissions are as expected
if [[ -f "$REDCLOAK_CONF" && "$(stat $REDCLOAK_CONF --format="%U:%G %a")" == "root:root 644" ]]
then
    # Fetch Redcloak installation directory (value of REDCLOAK_HOME)
    source "$REDCLOAK_CONF"
    REDCLOAK_AGENTID_FILE="${REDCLOAK_HOME}/etc/RedcloakAgentID"
    REDCLOAK_CONFIG_FILE="${REDCLOAK_HOME}/etc/config.bin"
    if [[ -n "$REDCLOAK_HOME" && -f "$REDCLOAK_AGENTID_FILE" && -f "$REDCLOAK_CONFIG_FILE" ]]
    then
        # Fetch Agent ID from RedcloakAgentID file
        REDCLOAK_AGENT_ID=$(cat $REDCLOAK_AGENTID_FILE)
        
        if [[ -n "$REDCLOAK_AGENT_ID" ]] 
        then
            echo "Redcloak Agent ID: ${REDCLOAK_AGENT_ID}"
            REDCLOAK_AGENT_ID="--redcloak-agent-id=${REDCLOAK_AGENT_ID}"
        else
            echo "Error fetching Redcloak Agent ID" >&2
        fi
        
        if [[ -n "$BIN" && -x "${BIN}/redcloakConfigParser" ]]
        then
            REDCLOAK_DOMAIN_ID=$(${BIN}/redcloakConfigParser ${REDCLOAK_CONFIG_FILE} 2>&1)
            parser_exitcode=$?
            if [[ $parser_exitcode == 0 && -n "$REDCLOAK_DOMAIN_ID" ]] 
            then
                echo "Redcloak Domain ID: ${REDCLOAK_DOMAIN_ID}"
                REDCLOAK_DOMAIN_ID="--redcloak-domain-id=${REDCLOAK_DOMAIN_ID}"
            else
                echo "Error fetching Redcloak Domain ID" >&2
            fi
        fi
    else
        echo "Error finding Redcloak installation directory from $REDCLOAK_CONF" >&2
    fi
    REDCLOAK_INSTALLED=1
else
    UNINSTALL_REDCLOAK=0
    REDCLOAK_INSTALLED=0
fi

MCS_CONFIG=${SOPHOS_INSTALL}/base/etc/sophosspl/mcs.config
if [[ -f "$MCS_CONFIG" ]]
then
    # Re-registering and mcs.config already exists
    source "$MCS_CONFIG"
    if [[ -n "${taegis_tenant_id}" ]] 
    then
        echo "Taegis Tenant ID: ${taegis_tenant_id}"
        TAEGIS_TENANT_ID="--taegis-tenant-id=${taegis_tenant_id}"
    fi
    
    if [[ -n "${taegis_host_id}" ]] 
    then
        echo "Taegis Host ID: ${taegis_host_id}"
        TAEGIS_HOST_ID="--taegis-host-id=${taegis_host_id}"
    fi
    
    if [[ -n "${redcloak_domain_id}" ]] 
    then
        echo "Redcloak Domain ID: ${redcloak_domain_id}"
        REDCLOAK_DOMAIN_ID="--redcloak-domain-id=${redcloak_domain_id}"
    fi
    
    if [[ -n "${redcloak_agent_id}" ]] 
    then
        echo "Redcloak Agent ID: ${redcloak_agent_id}"
        REDCLOAK_AGENT_ID="--redcloak-agent-id=${redcloak_agent_id}"
    fi
fi

${BIN}/installer credentials.txt ${MCS_TOKEN} ${MCS_URL} ${CUSTOMER_TOKEN_ARGUMENT} ${CMCSROUTER_MESSAGE_RELAYS} ${CMCSROUTER_PRODUCT_ARGUMENTS} "${REGISTRATION_GROUP_ARGS}" ${SOPHOS_LOG_LEVEL} ${TAEGIS_TENANT_ID} ${TAEGIS_HOST_ID} ${REDCLOAK_DOMAIN_ID} ${REDCLOAK_AGENT_ID} ${SKIP_TAEGIS_TENANT_ID_CHECK}
handle_register_errorcodes $?
#setup for running suldownloader
mkdir -p "${SOPHOS_INSTALL}/base/update/rootcerts"
mkdir -p "${SOPHOS_INSTALL}/base/update/var/updatescheduler"
mkdir -p "${SOPHOS_INSTALL}/var/sophosspl"
mkdir -p "${SOPHOS_INSTALL}/base/update/cache"
mkdir -p "${SOPHOS_INSTALL}/var/lock"
mkdir -p "${SOPHOS_INSTALL}/var/lock-sophosspl"

CERT=${BIN}/../rootca384.crt
[[ -n ${OVERRIDE_SOPHOS_CERTS} ]] && CERT=${OVERRIDE_SOPHOS_CERTS}/rootca384.crt
[[ -f ${CERT} ]] || CERT=${BIN}/../rootca384.crt
cp "$CERT" "${SOPHOS_INSTALL}/base/update/rootcerts/rootca384.crt"

[[ -n ${OVERRIDE_SOPHOS_CERTS} ]] && CERT=${OVERRIDE_SOPHOS_CERTS}/rootca384_dev.crt
[[ -n ${OVERRIDE_SOPHOS_CERTS} ]] && [ -f "${CERT}" ] && cp "${CERT}" "${SOPHOS_INSTALL}/base/update/rootcerts/rootca384_dev.crt"

[[ -n "${OVERRIDE_SUS_LOCATION}" ]] && echo "URLS = $OVERRIDE_SUS_LOCATION" >>"${SOPHOS_INSTALL}/base/update/var/sdds3_override_settings.ini"
[[ -n "${OVERRIDE_SUS_LOCATION}" ]] && echo "Overriding Sophos Update Service address with $OVERRIDE_SUS_LOCATION"
[[ -n "${OVERRIDE_CDN_LOCATION}" ]] && echo "CDN_URL = $OVERRIDE_CDN_LOCATION" >>"${SOPHOS_INSTALL}/base/update/var/sdds3_override_settings.ini"
[[ -n "${OVERRIDE_CDN_LOCATION}" ]] && echo "Overriding Sophos Update address with $OVERRIDE_CDN_LOCATION"
[[ -n "${OVERRIDE_SUITE}" ]] && echo "SUITES = $OVERRIDE_SUITE" >>"${SOPHOS_INSTALL}/base/update/var/sdds3_override_settings.ini"
[[ -n "${OVERRIDE_SUITE}" ]] && echo "Overriding SuiteName with $OVERRIDE_SUITE"
[[ -n "${OVERRIDE_RELEASE_GROUPS}" ]] && echo "GROUPS = $OVERRIDE_RELEASE_GROUPS" >>"${SOPHOS_INSTALL}/base/update/var/sdds3_override_settings.ini"
[[ -n "${OVERRIDE_RELEASE_GROUPS}" ]] && echo "Overriding release groups with $OVERRIDE_RELEASE_GROUPS"
[[ -n "${SDDS3_USE_HTTP}" ]] && echo "USE_HTTP = true" >>"${SOPHOS_INSTALL}/base/update/var/sdds3_override_settings.ini"
[[ -n "${USE_SDDS3}" ]] && echo "USE_SDDS3 = true" >>"${SOPHOS_INSTALL}/base/update/var/sdds3_override_settings.ini"

#copy mcs files in place to base
cp mcs.config "${SOPHOS_INSTALL}/base/etc"
cp mcsPolicy.config "${SOPHOS_INSTALL}/base/etc/sophosspl/mcs.config"
cp mcs_policy.config "${SOPHOS_INSTALL}/base/etc/sophosspl/mcs_policy.config"

if [[ -n ${https_proxy} ]]; then
    echo -n "${https_proxy}" >"${SOPHOS_INSTALL}/base/etc/savedproxy.config"
elif [[ -n ${HTTPS_PROXY} ]]; then
    echo -n "${HTTPS_PROXY}" >"${SOPHOS_INSTALL}/base/etc/savedproxy.config"
elif [[ -n ${http_proxy} ]]; then
    echo -n "${http_proxy}" >"${SOPHOS_INSTALL}/base/etc/savedproxy.config"
fi

echo "Downloading and installing ${PRODUCT_NAME}..."
INSTALL_OPTIONS_FILE="$INSTALL_OPTIONS_FILE" ${BIN}/SulDownloader update_config.json "${SOPHOS_INSTALL}/base/update/var/updatescheduler/update_report.json"
inst_ret=$?
handle_installer_errorcodes ${inst_ret}

if [[ $TAEGIS_INSTALLED == 1 ]]
then
    if [[ $UNINSTALL_TAEGIS == 1 ]]
    then
        if [[ -x $(which rpm) ]]
        then
            if rpm -e taegis-agent </dev/null
            then
                echo "Successfully uninstalled Taegis Agent"
            else
                echo "Failed to uninstall Taegis Agent: $?"
            fi
        elif [[ -x $(which dpkg) ]]
        then
            if DEBIAN_FRONTEND=noninteractive dpkg -P taegis-agent </dev/null
            then
                echo "Successfully uninstalled Taegis Agent"
            else
                echo "Failed to uninstall Taegis Agent: $?"
            fi
        else
            echo "Failed to uninstall Taegis Agent: unable to find rpm or dpkg"
        fi
    else
        echo "Deliberately not uninstalling Taegis Agent"
    fi
fi

if [[ $REDCLOAK_INSTALLED == 1 ]]
then
    if [[ $UNINSTALL_REDCLOAK == 1 ]]
    then
        if [[ -x $(which rpm) ]]
        then
            if rpm -e redcloak </dev/null
            then
                echo "Successfully uninstalled Redcloak"
            else
                echo "Failed to uninstall Redcloak: $?"
            fi
        elif [[ -x $(which dpkg) ]]
        then
            if DEBIAN_FRONTEND=noninteractive dpkg -r redcloak </dev/null
            then
                echo "Successfully uninstalled Redcloak"
            else
                echo "Failed to uninstall Redcloak: $?"
            fi
        else
            echo "Failed to uninstall Redcloak: unable to find rpm or dpkg"
        fi
    else
        echo "Deliberately not uninstalling Redcloak"
    fi
fi

write_check_result "summary" "successfully installed product on ${FINISHED_DATE}"
cleanup_and_exit ${inst_ret}
